def solve(s):
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            toks.append(int(s[i:j]))
            i = j
            continue
        toks.append(c)
        i += 1

    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def expr():
        v = term()
        while peek() in ('+', '-'):
            op = toks[pos[0]]
            pos[0] += 1
            r = term()
            v = v + r if op == '+' else v - r
        return v

    def term():
        v = unary()
        while peek() in ('*', '/'):
            op = toks[pos[0]]
            pos[0] += 1
            r = unary()
            if op == '*':
                v = v * r
            else:
                v = v // r
        return v

    def unary():
        t = peek()
        if t == '-':
            pos[0] += 1
            return -unary()
        if t == '+':
            pos[0] += 1
            return unary()
        return atom()

    def atom():
        t = peek()
        if t == '(':
            pos[0] += 1
            v = expr()
            pos[0] += 1  # ')'
            return v
        pos[0] += 1
        return t

    return expr()

def solve(text, k):
    counts = {}
    for raw in text.split():
        w = raw.lower().rstrip('.,!?;:')
        if not w:
            continue
        counts[w] = counts.get(w, 0) + 1
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return "\n".join("%s %d" % (w, c) for w, c in items[:k])

def solve(text):
    stats = {}
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if len(parts) < 2:
            continue
        level = parts[0]
        rest = parts[1]
        comp = rest.split(":", 1)[0].strip()
        if comp not in stats:
            stats[comp] = [0, 0]
        if level == "ERROR":
            stats[comp][0] += 1
        elif level == "WARN":
            stats[comp][1] += 1
    rows = sorted(stats.items(), key=lambda kv: (-kv[1][0], -kv[1][1], kv[0]))
    return "\n".join("%s %d %d" % (c, e, w) for c, (e, w) in rows)

