def winner(b):
    for a, c, d in LINES:
        if b[a] != '.' and b[a] == b[c] == b[d]:
            return b[a]
    return None


def other(s):
    return 'O' if s == 'X' else 'X'


def score(b, side, me, memo):
    key = (b, side)
    if key in memo:
        return memo[key]
    w = winner(b)
    if w is not None:
        r = 1 if w == me else -1
    elif '.' not in b:
        r = 0
    else:
        vals = []
        for i in range(9):
            if b[i] == '.':
                nb = b[:i] + side + b[i+1:]
                vals.append(score(nb, other(side), me, memo))
        r = max(vals) if side == me else min(vals)
    memo[key] = r
    return r


def solve(board, side):
    memo = {}
    best = None
    besti = -1
    for i in range(9):
        if board[i] == '.':
            nb = board[:i] + side + board[i+1:]
            v = score(nb, other(side), side, memo)
            if best is None or v > best:
                best = v
                besti = i
    return besti

