import heapq


def solve(edges, start, goal):
    adj = {}
    for tok in edges.split():
        if not tok:
            continue
        pair, _, wtxt = tok.partition(":")
        a, _, b = pair.partition("-")
        w = int(wtxt)
        adj.setdefault(a, []).append((b, w))
        adj.setdefault(b, []).append((a, w))
    if start == goal:
        return 0
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float('inf')):
            continue
        if u == goal:
            return d
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1

def solve(text):
    balance = 0
    rejected = 0
    for line in text.split("\n"):
        if line.strip() == "":
            continue
        parts = line.split()
        if len(parts) != 2:
            rejected += 1
            continue
        word, amt = parts
        if word not in ("deposit", "withdraw"):
            rejected += 1
            continue
        if not amt.isdigit():
            rejected += 1
            continue
        n = int(amt)
        if n <= 0:
            rejected += 1
            continue
        if word == "deposit":
            balance += n
        else:
            if balance >= n:
                balance -= n
            else:
                rejected += 1
    return "%d %d" % (balance, rejected)
